import ast, os, sys

# Scan every verl python file for `from verl.<x> import y` / `import verl.<x>` and
# verify the referenced module path resolves to an existing file (or package).
missing = set()
checked = 0
for root, dirs, files in os.walk('.'):
    if '__pycache__' in root:
        continue
    for f in files:
        if not f.endswith('.py') or f.startswith('._'):
            continue
        p = os.path.join(root, f)
        try:
            tree = ast.parse(open(p, encoding='utf-8').read())
        except Exception as e:
            print('PARSE FAIL', p, e); continue
        for node in ast.walk(tree):
            if isinstance(node, ast.ImportFrom) and node.module and node.module.startswith('verl'):
                mod = node.module
            elif isinstance(node, ast.Import):
                mods = [a.name for a in node.names]
            else:
                continue
            if isinstance(node, ast.Import):
                for m in mods:
                    if m.startswith('verl'):
                        # import verl.a.b -> module file a/b.py or a/b/__init__.py
                        base = m.replace('.', '/')
                        cand1 = base + '.py'
                        cand2 = base + '/__init__.py'
                        # for 'import verl.a' it means package verl.a; for 'import verl.a.b' need b under a
                        if not (os.path.exists(cand1) or os.path.exists(cand2)):
                            # could be submodule of a package; check parent pkg exists then flag leaf
                            missing.add(m)
                            checked += 1
            else:
                checked += 1
                base = mod.replace('.', '/')
                cand1 = base + '.py'
                cand2 = base + '/__init__.py'
                if not (os.path.exists(cand1) or os.path.exists(cand2)):
                    missing.add((p, mod))

print('checked references:', checked)
print('=== MISSING MODULES ===')
for item in sorted(missing, key=str):
    print(item)
EOF

