cd /workspace && python3 - <<'EOF'
import importlib, os, sys, pkgutil
import verl

failures = {}
def walk(pkgname):
    pkg = importlib.import_module(pkgname)
    path = getattr(pkg, '__path__', None)
    if path is None:
        return
    for m in pkgutil.iter_modules(path, pkgname + '.'):
        if m.name.split('.')[-1].startswith('_') and m.name.split('.')[-1] not in ('__init__',):
            continue
        full = m.name
        try:
            importlib.import_module(full)
        except ModuleNotFoundError as e:
            # only record genuinely missing *verl* submodule (matches our sabotage signature)
            if e.name and e.name.startswith('verl'):
                failures.setdefault(full, str(e))
        except Exception as e:
            failures.setdefault(full, f'{type(e).__name__}: {e}')
        else:
            if m.ispkg:
                walk(full)

walk('verl')
print(f'=== {len(failures)} modules with missing-verl-module errors ===')
for k, v in sorted(failures.items()):
    print(f'{k}\n    -> {v}')
EOF

